import pandas as pd, numpy as np, json, html, math, os, textwrap
from pathlib import Path

DATA='/app/benchmark/data.csv'
OUT='/app/output/final_report.html'
Path('/app/output').mkdir(parents=True, exist_ok=True)

df=pd.read_csv(DATA)
base=df[(df.sex=='both')&(df.age_group=='ALL')].copy()
all_countries=base.iso_code.nunique()
latest_year=int(base.year.max())
latest=base[base.year==latest_year].copy()

def fmt(x, digits=1):
    if x is None or (isinstance(x,float) and (math.isnan(x) or math.isinf(x))): return 'n/a'
    return f"{x:,.{digits}f}"
def fmt_pct(x, digits=1): return f"{x:,.{digits}f}%"
def esc(s): return html.escape(str(s))

yearly=base.groupby('year').agg(
    countries=('iso_code','nunique'),
    mean=('homicide_rate','mean'),
    median=('homicide_rate','median'),
    p25=('homicide_rate',lambda s:s.quantile(.25)),
    p75=('homicide_rate',lambda s:s.quantile(.75)),
    max=('homicide_rate','max')
).reset_index()
yearly['coverage_rate']=yearly['countries']/all_countries

def decade(y):
    if 1990<=y<=1999: return '1990s'
    if 2000<=y<=2009: return '2000s'
    if 2010<=y<=2019: return '2010s'
    if 2020<=y<=2023: return '2020s'
base['decade']=base.year.map(decade)
dec_year=yearly.assign(decade=yearly.year.map(decade)).groupby('decade').agg(
    avg_annual_mean=('mean','mean'), avg_annual_median=('median','mean'), avg_coverage=('coverage_rate','mean')
).reset_index()
dec_year['order']=dec_year.decade.map({'1990s':0,'2000s':1,'2010s':2,'2020s':3})
dec_year=dec_year.sort_values('order')
dec_year['avg_annual_mean_change_pct']=dec_year.avg_annual_mean.pct_change()*100

anchor_years=[2000,2010,2020,2023]
common=set.intersection(*[set(base.loc[base.year==y,'iso_code']) for y in anchor_years])
comp=base[base.iso_code.isin(common) & base.year.isin(anchor_years)]
comp_summary=comp.groupby('year').agg(countries=('iso_code','nunique'), mean=('homicide_rate','mean'), median=('homicide_rate','median')).reset_index()

top10=latest.sort_values('homicide_rate',ascending=False).head(10).copy()
bottom10=latest.sort_values('homicide_rate',ascending=True).head(10).copy()

sexall=df[df.age_group=='ALL'].copy()
sexp=sexall.pivot_table(index=['iso_code','country','year'], columns='sex', values='homicide_rate').reset_index()
sexp['ratio']=sexp['male']/sexp['female']
sexp=sexp.replace([np.inf,-np.inf], np.nan)
sex_year=sexp.dropna(subset=['male','female']).groupby('year').agg(
    countries=('iso_code','nunique'), male_mean=('male','mean'), female_mean=('female','mean'), ratio_median=('ratio','median')
).reset_index()
sex_year['aggregate_ratio']=sex_year['male_mean']/sex_year['female_mean']
sex_latest=sexp[(sexp.year==latest_year)].dropna(subset=['male','female']).copy()
sex_latest=sex_latest[sex_latest.female>0]
sex_top=sex_latest.sort_values('ratio',ascending=False).head(8).copy()

age_order=['0_9','10_14','15_17','18_19','20_24','25_29','30_44','45_59','60_PLUS']
age_label={'0_9':'0–9','10_14':'10–14','15_17':'15–17','18_19':'18–19','20_24':'20–24','25_29':'25–29','30_44':'30–44','45_59':'45–59','60_PLUS':'60+'}
age_specific=df[df.age_group!='ALL'].copy()
age_latest_year=int(age_specific.year.max())
age_latest=age_specific[age_specific.year==age_latest_year]
age_comb=age_latest[age_latest.sex.isin(['male','female'])].groupby(['iso_code','country','age_group']).agg(rate=('homicide_rate','mean')).reset_index()
age_comb_summary=age_comb.groupby('age_group').agg(countries=('iso_code','nunique'), mean=('rate','mean'), median=('rate','median')).reset_index()
age_comb_summary['age_order']=age_comb_summary.age_group.map({a:i for i,a in enumerate(age_order)})
age_comb_summary=age_comb_summary.sort_values('age_order')
age_sex=age_latest[age_latest.sex.isin(['male','female'])].groupby(['age_group','sex']).agg(countries=('iso_code','nunique'), mean=('homicide_rate','mean')).reset_index()
age_sex['age_order']=age_sex.age_group.map({a:i for i,a in enumerate(age_order)})
age_sex=age_sex.sort_values(['age_order','sex'])

obs=base.groupby(['iso_code','country']).agg(first_year=('year','min'), last_year=('year','max'), n=('year','nunique')).reset_index()
first=base.sort_values('year').groupby('iso_code').first().reset_index()[['iso_code','homicide_rate']].rename(columns={'homicide_rate':'first_rate'})
last=base.sort_values('year').groupby('iso_code').last().reset_index()[['iso_code','homicide_rate']].rename(columns={'homicide_rate':'last_rate'})
tr=obs.merge(first,on='iso_code').merge(last,on='iso_code')
tr['span']=tr.last_year-tr.first_year
tr['abs_change']=tr.last_rate-tr.first_rate
tr['pct_change']=np.where(tr.first_rate>0, tr.abs_change/tr.first_rate*100, np.nan)
tr_f=tr[(tr.span>=10)&(tr.n>=8)].copy()
tr_inc=tr_f.sort_values('abs_change',ascending=False).head(8).copy()
tr_dec=tr_f.sort_values('abs_change').head(8).copy()

# SVG utilities
BLUE='#2563eb'; NAVY='#0f172a'; SLATE='#64748b'; LIGHT='#e2e8f0'; GRID='#dbe4ef'; RED='#dc2626'; GREEN='#16a34a'; ORANGE='#f59e0b'; PURPLE='#7c3aed'; CYAN='#0891b2'

def svg_line_multi(series, width=900, height=360, title=None, ylabel='Rate per 100,000'):
    # series: list of dict label, data [(x,y)], color
    ml, mr, mt, mb = 58, 24, 24, 54
    xs=[x for s in series for x,y in s['data'] if y is not None and not math.isnan(y)]
    ys=[y for s in series for x,y in s['data'] if y is not None and not math.isnan(y)]
    xmin,xmax=min(xs),max(xs); ymin=0; ymax=max(ys)*1.08 if ys else 1
    def sx(x): return ml+(x-xmin)/(xmax-xmin)*(width-ml-mr)
    def sy(y): return height-mb-(y-ymin)/(ymax-ymin)*(height-mt-mb)
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title or ylabel)}">']
    out.append('<rect width="100%" height="100%" fill="white"/>')
    for i in range(5):
        val=ymin+(ymax-ymin)*i/4; y=sy(val)
        out.append(f'<line x1="{ml}" y1="{y:.1f}" x2="{width-mr}" y2="{y:.1f}" stroke="{GRID}" stroke-width="1"/>')
        out.append(f'<text x="{ml-10}" y="{y+4:.1f}" text-anchor="end" font-size="12" fill="{SLATE}">{fmt(val,1)}</text>')
    for yr in range((xmin//5)*5, xmax+1, 5):
        if yr<xmin: continue
        x=sx(yr)
        out.append(f'<text x="{x:.1f}" y="{height-24}" text-anchor="middle" font-size="12" fill="{SLATE}">{yr}</text>')
    out.append(f'<text x="18" y="{height/2}" transform="rotate(-90 18 {height/2})" text-anchor="middle" font-size="12" fill="{SLATE}">{esc(ylabel)}</text>')
    for s in series:
        pts=[]
        for x,y in s['data']:
            if y is None or math.isnan(y): continue
            pts.append(f'{sx(x):.1f},{sy(y):.1f}')
        if pts:
            out.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{s["color"]}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>')
            # last point label
            xlast,ylast=s['data'][-1]
            out.append(f'<circle cx="{sx(xlast):.1f}" cy="{sy(ylast):.1f}" r="4" fill="{s["color"]}"/>')
    # legend
    lx=ml; ly=18
    for s in series:
        out.append(f'<line x1="{lx}" y1="{ly}" x2="{lx+22}" y2="{ly}" stroke="{s["color"]}" stroke-width="3"/>')
        out.append(f'<text x="{lx+28}" y="{ly+4}" font-size="12" fill="{NAVY}">{esc(s["label"])}</text>')
        lx += 170
    out.append('</svg>')
    return ''.join(out)

def svg_barh(rows, label_col, value_col, width=900, height=420, color=BLUE, title=''):
    ml, mr, mt, mb = 190, 38, 20, 28
    vals=[float(r[value_col]) for _,r in rows.iterrows()]
    vmax=max(vals) if vals else 1
    n=len(vals); gap=8; barh=(height-mt-mb-gap*(n-1))/n
    def sx(v): return ml+v/vmax*(width-ml-mr)
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}"><rect width="100%" height="100%" fill="white"/>']
    for i,(_,r) in enumerate(rows.iterrows()):
        y=mt+i*(barh+gap); v=float(r[value_col]); w=max(0,sx(v)-ml)
        out.append(f'<text x="{ml-10}" y="{y+barh*0.65:.1f}" text-anchor="end" font-size="12" fill="{NAVY}">{esc(r[label_col])}</text>')
        out.append(f'<rect x="{ml}" y="{y}" width="{w:.1f}" height="{barh:.1f}" rx="4" fill="{color}" opacity="0.88"/>')
        out.append(f'<text x="{min(width-mr-4, ml+w+6):.1f}" y="{y+barh*0.65:.1f}" font-size="12" fill="{NAVY}">{fmt(v,1)}</text>')
    out.append('</svg>')
    return ''.join(out)

def svg_grouped_age(age_sex_df, width=900, height=380):
    ml, mr, mt, mb = 56, 22, 24, 58
    ages=age_order
    pivot=age_sex_df.pivot(index='age_group', columns='sex', values='mean').reindex(ages)
    ymax=float(np.nanmax(pivot.values))*1.18
    def sx(i): return ml+i/(len(ages)-1)*(width-ml-mr)
    def sy(v): return height-mb-v/ymax*(height-mt-mb)
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Age-specific homicide rates by sex"><rect width="100%" height="100%" fill="white"/>']
    for i in range(5):
        v=ymax*i/4; y=sy(v)
        out.append(f'<line x1="{ml}" y1="{y:.1f}" x2="{width-mr}" y2="{y:.1f}" stroke="{GRID}"/>')
        out.append(f'<text x="{ml-9}" y="{y+4:.1f}" text-anchor="end" font-size="12" fill="{SLATE}">{fmt(v,1)}</text>')
    for i,a in enumerate(ages):
        x=sx(i)
        out.append(f'<text x="{x:.1f}" y="{height-28}" text-anchor="middle" font-size="12" fill="{SLATE}">{age_label[a]}</text>')
    for sex,color in [('male',BLUE),('female',RED)]:
        pts=[]
        for i,a in enumerate(ages):
            v=pivot.loc[a,sex]
            if pd.notna(v): pts.append(f'{sx(i):.1f},{sy(float(v)):.1f}')
        out.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>')
        for i,a in enumerate(ages):
            v=pivot.loc[a,sex]
            if pd.notna(v): out.append(f'<circle cx="{sx(i):.1f}" cy="{sy(float(v)):.1f}" r="3.5" fill="{color}"/>')
    out.append(f'<line x1="{ml}" y1="18" x2="{ml+22}" y2="18" stroke="{BLUE}" stroke-width="3"/><text x="{ml+28}" y="22" font-size="12" fill="{NAVY}">Male</text>')
    out.append(f'<line x1="{ml+95}" y1="18" x2="{ml+117}" y2="18" stroke="{RED}" stroke-width="3"/><text x="{ml+123}" y="22" font-size="12" fill="{NAVY}">Female</text>')
    out.append('</svg>')
    return ''.join(out)

def table_html(df_, cols, headers=None, classes=''):
    headers=headers or cols
    out=[f'<table class="{classes}"><thead><tr>']
    for h in headers: out.append(f'<th>{esc(h)}</th>')
    out.append('</tr></thead><tbody>')
    for _,r in df_.iterrows():
        out.append('<tr>')
        for c in cols:
            v=r[c]
            if isinstance(v,(float,np.floating)): v=fmt(float(v),1)
            out.append(f'<td>{esc(v)}</td>')
        out.append('</tr>')
    out.append('</tbody></table>')
    return ''.join(out)

trend_svg=svg_line_multi([
    {'label':'Mean across reporting countries','data':list(zip(yearly.year.astype(int), yearly['mean'].astype(float))), 'color':BLUE},
    {'label':'Median across reporting countries','data':list(zip(yearly.year.astype(int), yearly['median'].astype(float))), 'color':GREEN},
], title='Global homicide trend')
coverage_svg=svg_line_multi([
    {'label':'Countries reporting','data':list(zip(yearly.year.astype(int), yearly['countries'].astype(float))), 'color':PURPLE},
], ylabel='Number of countries', title='Reporting coverage over time')
sex_svg=svg_line_multi([
    {'label':'Male mean','data':list(zip(sex_year.year.astype(int), sex_year['male_mean'].astype(float))), 'color':BLUE},
    {'label':'Female mean','data':list(zip(sex_year.year.astype(int), sex_year['female_mean'].astype(float))), 'color':RED},
    {'label':'Aggregate male:female ratio','data':list(zip(sex_year.year.astype(int), sex_year['aggregate_ratio'].astype(float))), 'color':ORANGE},
], ylabel='Rate / ratio', title='Gender disparity')
top_svg=svg_barh(top10.sort_values('homicide_rate'), 'country','homicide_rate', color=RED, title='Highest 2023 homicide rates')
bottom_svg=svg_barh(bottom10.sort_values('homicide_rate', ascending=False), 'country','homicide_rate', color=GREEN, title='Lowest 2023 homicide rates')
age_svg=svg_grouped_age(age_sex)
inc_svg=svg_barh(tr_inc.sort_values('abs_change'), 'country','abs_change', color=RED, title='Largest absolute increases')
dec_plot=tr_dec.copy(); dec_plot['decline']=-dec_plot['abs_change']
dec_svg=svg_barh(dec_plot.sort_values('decline'), 'country','decline', color=GREEN, title='Largest absolute decreases')

latest_median=float(latest.homicide_rate.median()); latest_mean=float(latest.homicide_rate.mean())
coverage=latest.iso_code.nunique()/all_countries*100
highest=top10.iloc[0]
sex_ratio=float(sex_latest.male.mean()/sex_latest.female.mean())
sex_med_ratio=float(sex_latest.ratio.median())
first_yr=int(yearly.iloc[0].year); first_mean=float(yearly.iloc[0]['mean']); first_median=float(yearly.iloc[0]['median']); first_countries=int(yearly.iloc[0].countries)
latest_countries=int(latest.iso_code.nunique())
change_1990_2023=(latest_median-first_median)/first_median*100
mean_change_1990_2023=(latest_mean-first_mean)/first_mean*100
most_recent_dec_change=float(dec_year.iloc[-1].avg_annual_mean_change_pct)
prev_dec_change=float(dec_year.iloc[-2].avg_annual_mean_change_pct)
peak_age=age_comb_summary.sort_values('mean', ascending=False).iloc[0]

# prepare tables
country_table=top10[['country','iso_code','homicide_rate']].copy(); country_table.columns=['Country','ISO','Rate']
low_table=bottom10[['country','iso_code','homicide_rate']].copy(); low_table.columns=['Country','ISO','Rate']
dec_table=dec_year.copy(); dec_table['Coverage']=dec_table.avg_coverage*100; dec_table['Change vs prior decade']=dec_table.avg_annual_mean_change_pct
dec_table=dec_table[['decade','avg_annual_mean','avg_annual_median','Coverage','Change vs prior decade']]
dec_table.columns=['Decade','Avg annual mean','Avg annual median','Avg reporting coverage','Change vs prior decade']
# custom format table
def dec_table_html():
    out='<table><thead><tr><th>Decade</th><th>Avg annual mean</th><th>Avg annual median</th><th>Avg reporting coverage</th><th>Mean change</th></tr></thead><tbody>'
