    return out+'</tbody></table>'

def trend_table_html(rows, direction):
    out='<table><thead><tr><th>Country</th><th>Period</th><th>Observations</th><th>First rate</th><th>Latest rate</th><th>Absolute change</th><th>% change</th></tr></thead><tbody>'
    for _,r in rows.iterrows():
        out+=f'<tr><td>{esc(r.country)}</td><td>{int(r.first_year)}–{int(r.last_year)}</td><td>{int(r.n)}</td><td>{fmt(r.first_rate,1)}</td><td>{fmt(r.last_rate,1)}</td><td>{fmt(r.abs_change,1)}</td><td>{"n/a" if pd.isna(r.pct_change) else fmt_pct(r.pct_change,1)}</td></tr>'
    return out+'</tbody></table>'

def sex_top_table():
    out='<table><thead><tr><th>Country</th><th>Male rate</th><th>Female rate</th><th>Male:female ratio</th></tr></thead><tbody>'
    for _,r in sex_top.iterrows():
        out+=f'<tr><td>{esc(r.country)}</td><td>{fmt(r.male,1)}</td><td>{fmt(r.female,1)}</td><td>{fmt(r.ratio,1)}×</td></tr>'
    return out+'</tbody></table>'

